# Тексты «Охотника»: (id, en, ru, заметка). ru — source_message, en — перевод в en.po.
# Заметка уходит комментарием в оба файла; "draft" — значение написано не дизайнером.

RU_COINS = "{n}|plural(one=золотую монету,few=золотые монеты,many=золотых монет,other=золотых монеты)"
EN_COINS = "{n}|plural(one=gold coin,other=gold coins)"


def coins(lang, arg):
    pattern = RU_COINS if lang == "ru" else EN_COINS
    return "{%s} %s" % (arg, pattern.replace("{n}", "{%s}" % arg))


