FILES["texts_hunter_dialogues"].extend([
    ("rh:text.dialogue.common.next", "Next", "Далее", None),
    ("rh:text.dialogue.common.back", "Ask about something else", "Спросить о другом", "draft"),
    ("rh:text.dialogue.common.end_talk", "End the conversation", "Закончить разговор", "draft"),
    ("rh:text.farid.ask_most_expensive", "— What is the most expensive wild beast ever sold here?", "— Какую самую дорогую дикарку здесь продавали?", "draft"),
    ("rh:text.farid.ask_price_factors", "— What does a wild beast's price depend on?", "— От чего зависит цена дикарки?", "draft"),
    ("rh:text.farid.sell", "— I want to sell my catch.", "— Хочу продать добычу.", "draft"),
    ("rh:text.menhunter.ask_gear", "— What would you advise me to take on the road?", "— Что посоветуешь взять в дорогу?", "draft"),
    ("rh:text.menhunter.ask_where_to_sell", "— Where can I sell my catch?", "— Где можно продать добычу?", "draft"),
    ("rh:text.notes.rome",
     "Eternal Rome is the only place where you can rest in peace and get gold for your catch. Living wild beasts are best taken to the central market: auctions are held there, and Farid always gives a fair price. Take dead and plain ones to the butcher on the northern street — he pays especially well for tattooed ones, and he can also teach you a thing or two about trade. At Menhunter's you can buy everything a hunt needs and sell rare trophies.<br>Before stepping into the Mists, check that you have enough supplies. And do not forget the crystal!",
     "Вечный Рим — единственное место, где можно спокойно отдохнуть и выручить золото за добычу. Живых дикарок лучше всего вести на центральный рынок: там идут аукционы, и Фарид всегда даст честную цену. Мертвых и неказистых неси мяснику с северной улицы — за татуированных он платит особенно щедро, а заодно может поучить торговле. У Менхантера можно купить все нужное для охоты и продать редкие трофеи.<br>Прежде чем шагнуть в Туманы, проверь, хватит ли припасов. И не забудь кристалл!",
     "draft"),
])
